static const char kDecodeError[] = "could not decode this part";

enum ConvKind {
    KIND_UTF8 = 0,
    KIND_ASCII,
    KIND_LATIN1,
    KIND_SINGLE,
    KIND_SJIS,
    KIND_GBK,
    KIND_GB18030,
    KIND_BIG5,
    KIND_EUCKR,
    KIND_EUCJP,
    KIND_ISO2022
};

struct ConvState {
    int kind;
    const uint16_t * single;
    const uint32_t * pairs;
    size_t pairs_n;
    unsigned char partial[8];
    int partial_len;
    int iso_mode;
    bool saw;
};

static thread_local bool g_saw_illegal = false;
static int mime_extended_charconv(const char * tocode, const char * fromcode, const char * str, size_t length,
    char * result, size_t * result_len);

static void append_utf8(std::string * out, uint32_t cp) {
    if (cp > 0x10FFFFu) cp = 0xFFFDu;
    if (cp < 0x80u) {
        out->push_back(static_cast<char>(cp));
    } else if (cp < 0x800u) {
        out->push_back(static_cast<char>(0xC0u | (cp >> 6)));
        out->push_back(static_cast<char>(0x80u | (cp & 0x3Fu)));
    } else if (cp < 0x10000u) {
        out->push_back(static_cast<char>(0xE0u | (cp >> 12)));
        out->push_back(static_cast<char>(0x80u | ((cp >> 6) & 0x3Fu)));
        out->push_back(static_cast<char>(0x80u | (cp & 0x3Fu)));
    } else {
        out->push_back(static_cast<char>(0xF0u | (cp >> 18)));
        out->push_back(static_cast<char>(0x80u | ((cp >> 12) & 0x3Fu)));
        out->push_back(static_cast<char>(0x80u | ((cp >> 6) & 0x3Fu)));
        out->push_back(static_cast<char>(0x80u | (cp & 0x3Fu)));
    }
}

static void emit_cp(std::string * out, ConvState * st, uint32_t cp) {
    if (cp == 0xFFFDu) st->saw = true;
    append_utf8(out, cp);
}

static bool pair_find(const uint32_t * table, size_t n, unsigned key, uint16_t * cp) {
    size_t lo = 0;
    size_t hi = n;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        unsigned got = table[mid] >> 16;
        if (got == key) {
            *cp = static_cast<uint16_t>(table[mid] & 0xFFFFu);
            return true;
        }
        if (got < key) lo = mid + 1u;
        else hi = mid;
    }
    return false;
}

static std::string canon_name(const char * name) {
    std::string out;
    if (name == nullptr) return out;
    for (const unsigned char * p = reinterpret_cast<const unsigned char *>(name); *p != 0; ++p) {
        unsigned char c = *p;
        if (c == ' ' || c == '\t' || c == '\r' || c == '\n') continue;
        if (c >= 'A' && c <= 'Z') c = static_cast<unsigned char>(c - 'A' + 'a');
        if (c == '_') c = '-';
        out.push_back(static_cast<char>(c));
    }
    return out;
}

